// ── Buy-by-community SEO data ─────────────────────────────────────────────
// Powers /buy-property-in-[community] programmatic pages. Slugs match the
// canonical community slugs used by /api/listings community filter and the
// /communities/[slug] detail pages.
//
// Each entry has a short unique SEO paragraph so Google doesn't see duplicate
// content across the pages. Stats are indicative (Q1 2026 Binayah data).
//
// shortIntro / why / vibe are localized (en/ru/ar/zh/vi). name, priceRange and
// yield are language-neutral (proper nouns + numbers) and stay as plain strings.

export type LocalizedText = { en: string; fr: string; ru: string; ar: string; zh: string; vi: string; he: string };

export interface BuyCommunity {
  slug: string;
  name: string;
  /** Primary community value as stored on listings (used for the API filter). Defaults to `name`. */
  apiName?: string;
  /** Slug for /communities/[slug] when the communities DB uses a different slug than this entry's `slug`. */
  communitySlug?: string;
  /** Additional community name variants stored on listings — tried as fallbacks when `apiName` returns 0. */
  synonyms?: string[];
  shortIntro: LocalizedText;
  why: LocalizedText;
  priceRange: string;
  yield: string;
  vibe: LocalizedText;
}

/** Pick the locale string, falling back to English. */
export function localizeCommunityText(t: LocalizedText, locale: string): string {
  return t[locale as keyof LocalizedText] ?? t.en;
}

